import concurrent.futures,urllib.request,urllib.error,html.parser,unicodedata,re,json,hashlib
class Visible(html.parser.HTMLParser):
 def __init__(self):super().__init__(convert_charrefs=True);self.hidden=0;self.parts=[]
 def handle_starttag(self,tag,attrs):
  if tag in ('script','style','noscript','template'):self.hidden+=1
 def handle_endtag(self,tag):
  if tag in ('script','style','noscript','template') and self.hidden:self.hidden-=1
 def handle_data(self,data):
  if not self.hidden:self.parts.append(data)
def norm(text):
 return re.sub(r'\s+',' ',''.join(c for c in unicodedata.normalize('NFKD',text.casefold()) if not unicodedata.combining(c))).strip()
targets=[
