def probe(item):
 name,url,terms=item
 out={'source':name,'scope':'public provider documentation, no credentials or private records'}
 try:
  req=urllib.request.Request(url,headers={'User-Agent':'Telecom-PT research public documentation'})
  with urllib.request.urlopen(req,timeout=12) as res:
   b=res.read(2097153);out.update(status=res.status,bytes_examined=min(len(b),2097152),truncated=len(b)>2097152)
  p=Visible();p.feed(b[:2097152].decode('utf-8',errors='replace'));t=norm(' '.join(p.parts))
  out['visible_terms']={term:norm(term) in t for term in terms}
  out['matched']=sum(out['visible_terms'].values())
  out['document_sha256']=hashlib.sha256(b[:2097152]).hexdigest()
 except urllib.error.HTTPError as e:out['status']=e.code
 except Exception as e:out['error']=type(e).__name__
 return out
